import{d as u,C as t,o as g,c,j as a,a as s,E as o,a3 as x}from"./chunks/framework.Q4yG9rk_.js";const f=JSON.parse('{"title":"道德经第五十四章","description":"从善建善抱到身家乡国天下，理解修德的推广及以此观之。","frontmatter":{"title":"道德经第五十四章","description":"从善建善抱到身家乡国天下，理解修德的推广及以此观之。","category":"guide","aliases":["道德经第五十四章","老子第五十四章","dao de jing chapter 54"],"source":["王弼《道德真经注》卷三"]},"headers":[],"relativePath":"daoism/dao-de-jing/chapter-54.md","filePath":"daoism/dao-de-jing/chapter-54.md","lastUpdated":1794189804000}'),b={name:"daoism/dao-de-jing/chapter-54.md"},_=u({...b,setup(m){const n=[{id:"rooted-building-and-holding",label:"善建者不拔",showLabel:!0,sentences:[["善",{text:"建",glossary:"jian"},"者不",{text:"拔",glossary:"ba"},"，善",{text:"抱",glossary:"bao"},"者不脱，子孙",{text:"祭祀",glossary:"jisi"},"不",{text:"辍",glossary:"chuo"},"。"]],note:["【白话】善于建立的，不会被拔除；善于持抱的，不会脱失。这种道由子孙相传，祭祀因而得以不断。","【王弼注择要】「固其根而后营其末，故不拔也。」善抱的注是「不贪于多，齐其所能，故不脱也」；祭祀下注说「子孙传此道以祭祀则不辍也」。","【读法】建、抱都从稳固的根本与能力分际来读，不只靠外力控制。祭祀不辍在此是古代传承的表达，不是只要行某个仪式就保证家族永续。"]},{id:"cultivation-in-self-and-family",label:"修之于身，其德乃真",showLabel:!0,sentences:[[{text:"修",glossary:"xiu"},"之于身，其",{text:"德",glossary:"de"},"乃真；",{text:"修",glossary:"xiu"},"之于家，其",{text:"德",glossary:"de"},"乃",{text:"余",glossary:"yu"},"；"]],note:["【白话】在自身修行此道，德才真实不虚；将它实行于家，德便不只存于一身，而有余益及人。","【王弼注择要】「以身及人也。」注又说「修之不废，所施转大」，将推广连到持续不废的修为。","【读法】真与余不只是数量增减：先有自身真实的实行，再有及人的作用。家庭是本章的一层，不要求每位读者先拥有某种特定家庭形式才可修德。"]},{id:"cultivation-beyond-the-household",label:"修之于乡，其德乃长",showLabel:!0,sentences:[[{text:"修",glossary:"xiu"},"之于乡，其",{text:"德",glossary:"de"},"乃",{text:"长",glossary:"zhang"},"；",{text:"修",glossary:"xiu"},"之于国，其",{text:"德",glossary:"de"},"乃丰；",{text:"修",glossary:"xiu"},"之于天下，其",{text:"德",glossary:"de"},"乃",{text:"普",glossary:"pu"},"。"]],note:["【白话】实行于乡里，德的作用便增长；实行于国，便丰厚；实行于天下，便普遍地惠及。身、家之后，成用的范围继续展开。","【读法】承前段所施转大的王注，长读 zhǎng、作增长，丰为丰厚，普为普及。所据此三句未另见独立短注，不补造逐句原注。","【读法】本章给出由近及远的修为方向，不等于只要一人品德良好，制度与公共问题就自动解决；现代应用仍须考虑各层具体条件。"]},{id:"observing-at-each-scope",label:"以身观身",showLabel:!0,sentences:[["故以身",{text:"观",glossary:"guan"},"身，以家",{text:"观",glossary:"guan"},"家，以乡",{text:"观",glossary:"guan"},"乡，以国",{text:"观",glossary:"guan"},"国，以天下",{text:"观",glossary:"guan"},"天下。"]],note:["【白话】所以，依自身修道的情形观照他身，依家观家，依乡观乡，依国观国；进到天下这一层，则从天下百姓之心观其道。前面怎样修，这里便怎样推观。","【王弼注择要】以身至国之后注「彼皆然也」；以天下观天下下注「以天下百姓心观天下之道也」，并将逆顺吉凶与人之道相参。","【读法】王弼既从自身推知，也把百姓心纳入天下之观，不能把它缩成个人感受即一切事实。各层观察要回到该层的人与条件，不以一个尺度机械覆盖。"]},{id:"knowing-through-this",label:"吾何以知天下然哉",showLabel:!0,sentences:[["吾何以知天下然哉？以此。"]],note:["【白话】我凭什么知道天下的道理是这样呢？凭的就是上面从修身及人、由身而观天下的这条路径。","【王弼注择要】「此，上之所云也。」注又说「察己以知之，不求于外也」，并联系不出户知天下的说法。","【读法】以此指回整段修与观，并非另设一个神秘方法。可与第四十七章相参：识所由有助于推知，具体判断仍须听取不同处境并接受事实检验。"]}],r=[{id:"jian",term:"建",sense:1},{id:"ba",term:"拔",sense:1},{id:"bao",term:"抱",sense:1},{id:"chuo",term:"辍",sense:1},{id:"jisi",term:"祭祀",sense:1},{id:"xiu",term:"修",sense:1},{id:"de",term:"德",sense:1},{id:"yu",term:"余",sense:1},{id:"zhang",term:"长",sense:2},{id:"pu",term:"普",sense:1},{id:"guan",term:"观",sense:1}];return(p,e)=>{const i=t("DaoReadingPrelude"),l=t("DaoTextReading"),d=t("DaoLineGuide"),h=t("DaoKeywordCards");return g(),c("div",null,[e[0]||(e[0]=a("h1",{id:"道德经第五十四章",tabindex:"-1"},[s("道德经第五十四章 "),a("a",{class:"header-anchor",href:"#道德经第五十四章","aria-label":'Permalink to "道德经第五十四章"'},"​")],-1)),o(i,{title:"从自身到天下，修与观怎样一层层展开",summary:"本章先说善建、善抱的稳固，再由身、家、乡、国推到天下，末段以观回看各层。王弼以固根而营末、不贪多而齐所能解释起笔，又以从自身及人、从百姓心观天下贯通修与观。",points:[{label:"先读",text:"不拔不脱由固根与不贪多而来，不只说抓得更紧、建得更硬。"},{label:"再辨",text:"真、余、长、丰、普随身家乡国天下铺展，推广以持续修为前提。"},{label:"后看",text:"以身观身到以天下观天下，依王注看共同所由与百姓心，不凭一己体验包办天下。"}],hint:"辍读 chuò，祭祀读 jì sì，观读 guān；其德乃长的长读 zhǎng，取增长义。"}),e[1]||(e[1]=a("h2",{id:"【原典层】原文与段释义",tabindex:"-1"},[s("【原典层】原文与段释义 "),a("a",{class:"header-anchor",href:"#【原典层】原文与段释义","aria-label":'Permalink to "【原典层】原文与段释义"'},"​")],-1)),o(l,{sections:n,glossary:r}),e[2]||(e[2]=a("h2",{id:"【原典层】核心句引读",tabindex:"-1"},[s("【原典层】核心句引读 "),a("a",{class:"header-anchor",href:"#【原典层】核心句引读","aria-label":'Permalink to "【原典层】核心句引读"'},"​")],-1)),o(d,{lines:[{text:"善建者不拔，善抱者不脱，子孙祭祀不辍。",tone:"固根与不贪多",guide:"把稳固连到根本与所能，不以外在控制代替传承。"},{text:"修之于身，其德乃真；修之于家，其德乃余；",tone:"从真实实行到及人",guide:"推广的起点是自身修之不废，而非先求声名和规模。"},{text:"故以身观身，以家观家，以乡观乡，以国观国，以天下观天下。",tone:"修与观相应",guide:"从自身推观，也依百姓心与不同层次的具体条件理解天下。"}]}),e[3]||(e[3]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[s("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),o(h,{items:r}),e[4]||(e[4]=x('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-建抱、修德与观天下是什么关系" tabindex="-1">象：建抱、修德与观天下是什么关系？ <a class="header-anchor" href="#象-建抱、修德与观天下是什么关系" aria-label="Permalink to &quot;象：建抱、修德与观天下是什么关系？&quot;">​</a></h3><p>起笔先说根本稳固、持抱不失，修德段再把这种道的实行从自身推广，观的段落回看各层如何成立。三部分由固本、持续实行与推观相接。</p><h3 id="理-为什么推广之前先说修之于身" tabindex="-1">理：为什么推广之前先说修之于身？ <a class="header-anchor" href="#理-为什么推广之前先说修之于身" aria-label="Permalink to &quot;理：为什么推广之前先说修之于身？&quot;">​</a></h3><p>王弼用以身及人和修之不废说明推广。若自己没有真实实行，范围的扩大便可能只剩名目；其德乃真把后面的余、长、丰、普系在一个可持续的起点上。</p><h3 id="用-今天怎样把修与观配合起来" tabindex="-1">用：今天怎样把修与观配合起来？ <a class="header-anchor" href="#用-今天怎样把修与观配合起来" aria-label="Permalink to &quot;用：今天怎样把修与观配合起来？&quot;">​</a></h3><p>先在能负责的范围内落实，再观察效果能否在更大范围成立。推广时要听取那里的人、资源和条件，不能仅因自己受用便断定对所有人都适用。</p><h2 id="【解读层】现代解读与启发" tabindex="-1">【解读层】现代解读与启发 <a class="header-anchor" href="#【解读层】现代解读与启发" aria-label="Permalink to &quot;【解读层】现代解读与启发&quot;">​</a></h2><p><strong>扩展之前先核实根基。</strong> 一项做法在小范围运作稳定，再考虑怎样推广。固根与不贪多，提醒人让规模与实际能力相称。</p><p><strong>推广也需要重新观察。</strong> 从个人到家庭、组织与公共事务，责任和条件都会变化。保留共同的原则，同时重新理解每一层具体需要，才可能使影响持续。</p><h2 id="【个人记录】我的笔记" tabindex="-1">【个人记录】我的笔记 <a class="header-anchor" href="#【个人记录】我的笔记" aria-label="Permalink to &quot;【个人记录】我的笔记&quot;">​</a></h2><p>留给自己的续读问题：我想推广的做法，自己是否已经持续实行？范围扩大之后，我有没有重新听见相关的人，而不是只复制原来的经验？</p><h2 id="校读说明与参考来源" tabindex="-1">校读说明与参考来源 <a class="header-anchor" href="#校读说明与参考来源" aria-label="Permalink to &quot;校读说明与参考来源&quot;">​</a></h2><ul><li>正文与标点沿本站保留，据卷三 014a–014b 电子录文核对；下页 015a 前本章已收束。</li><li>本站善建者不拔，录文作善建不拔；本站子孙祭祀不辍，录文作子孙以祭祀不辍，保留并列明者、以的有无。</li><li>长复用德增长义；观依王弼彼皆然、以天下百姓心及察己的解释贯通，不把本站现代推广方法冒作古注原话。</li></ul><p>参考：<a href="https://github.com/kanripo/KR5c0073/blob/b988441bd55861741c850e1dff4a2d4f895daf3d/KR5c0073_003.txt" target="_blank" rel="noreferrer">王弼《道德真经注》卷三 HFL 本电子录文，014a–014b</a>。</p>',15))])}}});export{f as __pageData,_ as default};
